const master_log = global.get("master_log") || [];
const new_entries = msg.payload;

global.set("master_log", master_log.concat(new_entries));

msg.payload = new_entries;

return msg;

const master_log = global.get("master_log") || [];
const existing_ids = new Set(master_log.map(entry => entry.id));

const duplicates = msg.payload.filter(entry => existing_ids.has(entry.id));
msg.payload = msg.payload.filter(entry => !existing_ids.has(entry.id));

if (duplicates.length > 0) {
    node.warn({ msg: "Duplicate entries removed", duplicates: duplicates });
}

return msg;

const entries = msg.payload;

if (entries.length > 0) {
    const newestEntry = entries.reduce((a, b) => a.timeCreated > b.timeCreated ? a : b); // find newest log entry
    const client = newestEntry.client.charAt(0) + newestEntry.client.slice(1); // extract client

    global.set(`last_${client}_timestamp`, newestEntry.timeCreated); // update global timestamp variable
}

return msg;
